const config = $('Set Config').first().json;
const commits = $('Fetch Commits').all().map(item => item.json);
const issues = $('Fetch Closed Issues').all().map(item => item.json);
const prs = $('Fetch Merged PRs').all().map(item => item.json);

const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const today = new Date();

const mergedPRs = prs.filter(pr => pr.merged_at && new Date(pr.merged_at) > weekAgo);

const context = {
  repo: config.repo,
  period: `${weekAgo.toISOString().slice(0, 10)} to ${today.toISOString().slice(0, 10)}`,
  stats: { commits: commits.length, issuesClosed: issues.length, prsMerged: mergedPRs.length },
  commits: commits.slice(0, 25).map(c => ({
    message: c.commit?.message?.split('\n')[0] || '',
    author: c.commit?.author?.name || c.author?.login || 'unknown',
    sha: c.sha?.slice(0, 7) || '',
    date: c.commit?.author?.date || ''
  })),
  issuesClosed: issues.slice(0, 20).map(i => ({
    number: i.number,
    title: i.title,
    closedBy: i.closed_by?.login || i.user?.login || 'unknown',
    labels: (i.labels || []).map(label => label.name)
  })),
  prsMerged: mergedPRs.slice(0, 20).map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user?.login || 'unknown',
    mergedAt: pr.merged_at
  }))
};

const prompt = `You are a technical project manager writing a concise weekly development summary.

Repository: ${context.repo}
Period: ${context.period}

Stats:
- ${context.stats.commits} commits
- ${context.stats.issuesClosed} issues closed
- ${context.stats.prsMerged} pull requests merged

Recent commits:
${context.commits.map(c => `- ${c.message} (${c.author}, ${c.sha})`).join('\n') || '- None'}

Closed issues:
${context.issuesClosed.map(i => `- #${i.number} ${i.title} [${i.labels.join(', ')}]`).join('\n') || '- None'}

Merged pull requests:
${context.prsMerged.map(pr => `- #${pr.number} ${pr.title} by ${pr.author}`).join('\n') || '- None'}

Write in ${config.language || 'English'}. Include:
1. A one-line headline capturing the week
2. 2-3 bullet key accomplishments
3. Notable changes or decisions
4. One looking-ahead sentence

Keep it under 300 words and use a professional, friendly tone.`;

return [{ json: { prompt, context, config } }];

const response = $input.first().json;
const prepared = $('Prepare Claude Prompt').first().json;
const text = response.content?.[0]?.text || 'No summary generated.';
const date = new Date().toISOString().slice(0, 10);
const context = prepared.context;
const config = prepared.config;

const subject = `Weekly Dev Summary — ${context.repo} (${context.period})`;
const footer = `\n\n---\nGenerated by Claude + n8n on ${date}\n${context.stats.commits} commits · ${context.stats.issuesClosed} issues · ${context.stats.prsMerged} PRs`;
const body = `${text}${footer}`;

return [{ json: { subject, body, config } }];

return await (async () => {
const { subject, body, config } = $input.first().json;
const method = (config.delivery_method || 'slack').toLowerCase();

async function postJson(url, payload, headers = {}) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...headers },
    body: JSON.stringify(payload),
  });
  if (!response.ok) {
    throw new Error(`Delivery failed: ${response.status} ${await response.text()}`);
  }
  return response.text();
}

let result;
if (method === 'slack') {
  result = await postJson(config.slack_webhook, { text: `*${subject}*\n${body}` });
} else if (method === 'discord') {
  result = await postJson(config.discord_webhook, { content: `**${subject}**\n${body}` });
} else if (method === 'email') {
  result = await postJson('https://api.resend.com/emails', {
    from: config.email_from,
    to: config.email_to,
    subject,
    text: body,
  }, { Authorization: `Bearer ${config.resend_key}` });
} else {
  throw new Error(`Unsupported delivery_method: ${method}`);
}

return [{ json: { delivered: true, method, subject, response: result } }];
})();
